// ===== COLONNA =====

S.push({id:`lbp-triage`,d:`Colonna`,t:`Low back pain: triage e patologie specifiche`,nw:1,
sub:`Safe to treat · treat with precautions · refer`,
mat:[MLB],
key:[`Il triage divide in: sicuro da trattare, trattare con precauzioni, inviare`,`Le red flags sono 163 segni e sintomi: l'80% dei pazienti con LBP acuto ne ha almeno una, ma <1% ha una patologia seria → usarle in combinazione con anamnesi ed esame`,`Patologie specifiche: cauda equina, frattura vertebrale, infezione, neoplasia, patologie reumatiche, stenosi, radicolopatia`,`La frattura è la patologia seria più comune, la neoplasia la seconda`],
tab:[{t:`Frattura vertebrale (lezione)`,h:[`Aspetto`,`Dettagli`],r:[[`Fattori di rischio`,`Età avanzata, trauma severo, corticosteroidi prolungati, sesso femminile, frattura vertebrale precedente`],[`Fratture da insufficienza`,`Osteoporosi, steroidi 7,5 mg per >3 mesi, storia oncologica, artrite reumatoide, diabete, deficit di vitamina D, alcol, fumo >20, restrizione dietetica, disturbi alimentari, malassorbimento (Crohn)`],[`Epidemiologia`,`70% toraciche, 20% lombari, 10% cervicali; per lo più T8-L4; 12% delle donne 50-70 anni, fino al 20% oltre i 70; 70% non diagnosticate`],[`Clinica`,`Dolore improvviso e severo toraco-lombare, aumenta in carico, movimenti attivi limitati e dolorosi, talvolta spinosa prominente e cifosi aumentata, dolore alla percussione`],[`Esame`,`RX`]]},
{t:`Neoplasia (lezione)`,h:[`Aspetto`,`Dettagli`],r:[[`Fattore di rischio`,`Storia di tumore (seno, prostata, polmone, rene, tiroide); il rischio aumenta con l'età`],[`Sintomi`,`Dolore severo progressivo e costante, notturno, malessere sistemico, calo ponderale inspiegato, dolore "diverso dal solito"`],[`Esami`,`RM, TC, esami del sangue`]]},
{t:`Esame neurologico (lezione)`,h:[`Livello`,`Riflesso`,`Miotomo`],r:[[`(L1) L2 (L3)`,`—`,`Ileopsoas`],[`L3 (L4)`,`Rotuleo (L3-L4)`,`Quadricipite`],[`L4 (L5)`,`—`,`Tibiale anteriore`],[`L5 (S1)`,`—`,`Estensore lungo dell'alluce`],[`(L5) S1 (S2)`,`Achilleo (S1-S2)`,`Gastrocnemio e soleo`],[`S2`,`—`,`Flessori lunghi delle dita`]],n:`Sensibilità per dermatomi; esame neurodinamico con SLR e PKB (prone knee bend).`}],
red:[`Cauda equina: ritenzione o incontinenza urinaria, anestesia a sella, deficit motorio progressivo bilaterale → invio urgente.`,`Febbre, immunodepressione, uso di droghe endovena: infezione.`,`Storia oncologica, calo ponderale, dolore notturno costante: neoplasia.`,`Trauma, osteoporosi, steroidi: frattura.`],
yel:[`Distress psicologico, convinzioni negative, scarsa fiducia nel recupero: valutare con STarT Back o Örebro (vedi scheda LBP aspecifico).`],
tst:[[`Esame neurologico`,`Sensibilità, riflessi, forza per miotomi.`,`Radicolopatia o compromissione neurologica.`],[`SLR e PKB`,`Elevazione dell'arto esteso; flessione del ginocchio da prono.`,`Meccanosensibilità neurale (L4-S1; L2-L4).`],[`Percussione delle spinose`,`Percussione dei processi spinosi.`,`Dolore focale: sospetta frattura.`]],
f:[[`Finucane et al. 2020 – framework internazionale sulle red flags spinali (JOSPT)`,`Finucane 2020 international framework red flags potential serious spinal pathologies`,`PMID 32438853`],[`Hartvigsen et al. 2018 – What low back pain is and why we need to pay attention (Lancet)`,`Hartvigsen 2018 what low back pain is Lancet`,`PMID 29573870`]]});

S.push({id:`lbp-aspecifico`,d:`Colonna`,t:`Low back pain aspecifico (acuto e cronico)`,nw:1,
sub:`Modello biopsicosociale, educazione, attività ed esercizio`,
mat:[MLB],
key:[`Il LBP è un sintomo, non una malattia: nella quasi totalità dei casi la sorgente nocicettiva specifica non si può identificare`,`Prima causa di disabilità al mondo (Global Burden of Disease)`,`L'imaging non ha ruolo nel LBP aspecifico: aumenta disabilità e assenze dal lavoro (in Italia il 56% fa imaging)`,`Restare attivi, educare e rassicurare, esercizio adattato al paziente; la terapia manuale aiuta a facilitare il movimento`],
inq:[`Dati: quasi ogni adulto avrà LBP; 40% tra 9 e 18 anni; più comune tra 40 e 69`,`La maggior parte degli episodi migliora entro 6 settimane; 2/3 hanno ancora dolore a 3 mesi; 33% recidiva entro un anno; nel 10-40% diventa persistente e disabilitante`,`LBP acuto: circa il 50% recupera completamente in 2-3 settimane con una buona prima presa in carico; 1/3 non ricorda un trigger; episodi più frequenti al mattino`,`Cronico: dolore oltre 3 mesi, da minima interferenza a grave disabilità`,`Meccanismi: nocicettivo, neuropatico, nociplastico (Nijs 2024)`,`Il dolore è un output protettivo del cervello quando le "prove di pericolo" superano quelle di sicurezza (IASP 2020)`,`Poca evidenza che il LBP sia associato a perdita di "core stability"; invece co-contrazione e guarding aumentati sono associati a recidiva e persistenza (O'Sullivan 2014)`],
tab:[{t:`Fattori di rischio e prognosi (lezione)`,h:[`Tipo`,`Fattori`],r:[[`Rischio di episodio`,`Episodi precedenti, condizioni croniche (asma, cefalea, diabete), sintomi depressivi, fumo, obesità, bassa attività fisica, genetica, esposizione lavorativa`],[`Esito sfavorevole`,`Alta disabilità, dolore all'arto inferiore, età, cattiva salute, distress psicosociale, cognizioni negative (credenze, attenzione, coping, autoefficacia), cattivi rapporti al lavoro, lavoro pesante, compensi economici`],[`Predittori`,`Disturbi del sonno, stress, umore depresso, ansia; dolore intenso + distress + dolore alla gamba o multisito → LBP disabilitante; credenze negative; aspettative di recupero (forte associazione con il ritorno al lavoro)`],[`Acuto → cronico`,`LBP con dolore alla gamba; percorsi di cura non concordanti con le linee guida nella fase iniziale`]]},
{t:`Credenze che peggiorano disabilità e recupero (O'Sullivan 2014)`,h:[`Credenza`,`Risposta educativa`],r:[[`"So che peggiorerà"`,`Prognosi generalmente favorevole, recidive gestibili`],[`"Male = danno"`,`Il dolore è una protezione, non una misura del danno`],[`"I movimenti che fanno male vanno evitati"`,`Esposizione graduale, movimento normale e sicuro`]]},
{t:`Imaging nei asintomatici (Brinjikji 2015)`,h:[`Concetto`,`Implicazione`],r:[[`Degenerazione discale, protrusioni e Modic sono frequenti anche senza dolore`,`Correlano poco con dolore e disabilità e non predicono il LBP futuro`],[`Imaging indicato solo se`,`Sospetto di patologia seria, risposta insoddisfacente al conservativo o progressione inspiegata, imaging che cambia la gestione`]],n:`Modic: tipo 1 tessuto fibrovascolare/edema, tipo 2 sostituzione grassa, tipo 3 sclerosi. Il tipo 1 può correlare con il LBP.`}],
sez:[{h:`Valutazione soggettiva e fisica (lezione)`,b:[`Soggettiva: body chart, comportamento dei sintomi nelle 24 h, storia, fattori psicosociali, domande speciali, indagini, stile di vita`,`Screening del rischio di cronicità: Keele STarT Back Tool, Örebro short form; valutare presto per stratificare`,`Fisica: ispezione, dimostrazione funzionale, movimenti attivi, forza, esame neurologico e neurodinamico, palpazione e passivi`,`Pattern adattivi vs maladattivi: es. nella stenosi la riduzione funzionale della lordosi è protettiva, l'aumento con guarding è maladattivo`,`Cosa vuole il paziente: validazione, diagnosi e cura, rassicurazione sull'assenza di patologia, tornare ad attività significative`]},
{h:`Gestione (lezione e linee guida)`,b:[`Educazione e rassicurazione: causa seria molto improbabile, nessuna necessità di esami; spiegare causa, prognosi e cosa fare; correggere le misconcezioni; promuovere l'autogestione`,`Acuto: restare il più attivi possibile, se possibile al lavoro; modificare l'attività solo con evidente strain tissutale; progressione contingente al tempo, non al dolore`,`Esercizio: adattato a caratteristiche, convinzioni, preferenze, contesto e intensità dei sintomi; benefici su forza, oppioidi endogeni, umore, kinesiofobia, riorganizzazione corticale`,`Cammino: WalkBack trial (Pocovi 2024, Lancet) – obiettivo 5 volte/settimana per ≥30 min entro 6 mesi; riduce recidive e disabilità fino a 12 mesi`,`Corsa: sicura, i runner amatoriali hanno meno LBP; nello studio di Neason 2024 i miglioramenti si avvicinano ma non raggiungono la soglia clinica`,`Terapia manuale: in acuto/subacuto se limita il movimento, per validare, educare, ridurre la minaccia e guidare il cambiamento`,`Lavoro: evitare comportamenti di evitamento; modifiche temporanee solo in acuto`,`Stile di vita: sedentarietà, stress, sonno, fumo, obesità`,`Cronico: maggiore enfasi sui trattamenti non farmacologici e sui fattori che facilitano il dolore`]}],
red:[`Vedi scheda Triage: cauda equina, frattura, infezione, neoplasia.`],
yel:[`Paura-evitamento, catastrofizzazione, ansia, depressione, credenze negative, scarsa aspettativa di recupero, problemi lavorativi.`],
tst:[[`Keele STarT Back Tool`,`9 domande; stratifica rischio basso, medio, alto.`,`Indirizza l'intensità della presa in carico.`],[`Örebro short form`,`10 item; nella lezione cut-off ≤50 basso rischio, >50 alto rischio.`,`Rischio di scarso recupero.`],[`Dimostrazione funzionale`,`Il paziente mostra il movimento che provoca o teme (sedersi, alzarsi, piegarsi, girarsi nel letto).`,`Guarding, bracing, velocità ridotta: target per l'esposizione.`]],
ex:[[`Rilassamento e respiro nei movimenti temuti`,`c`,`5-10 min · quotidiano`,`Respirazione diaframmatica e rilascio del guarding durante seduto-in piedi, rotolare nel letto, piegarsi.`,`Irrigidire il tronco (bracing).`,`Più velocità e naturalezza del movimento.`],[`Esposizione graduale per posizioni`,`m`,`3×8-10 · quotidiano`,`Da sdraiati a seduti a in piedi; sperimentare posizioni diverse (es. sollevare la gamba, quadrupedia).`,`Evitare sistematicamente la flessione.`,`Compiti reali e carico esterno.`],[`Programma di cammino`,`c`,`Fino a 5×30 min/sett`,`Aumento progressivo di durata e frequenza (WalkBack).`,`Basare la quantità sul dolore del giorno.`,`Ritmo più sostenuto o corsa.`],[`Rinforzo generale e sollevamenti`,`f`,`2-3×8-12 · RPE 6-8 · 2-3/sett`,`Deadlift, squat, row: sollevare anche flettendo la schiena se tollerato (Saraceni 2020).`,`Paura della flessione lombare come regola.`,`Carico progressivo.`]],
fasi:[{n:`Acuto`,w:`0-6 sett.`,o:`Rassicurare, restare attivi, normalizzare il movimento`,k:`Educazione, autogestione (es. borsa calda), terapia manuale se limita il movimento, attività contingente al tempo`,c:`Funzione in miglioramento, meno paura`,e:[0,1,2]},{n:`Subacuto`,w:`6-12 sett.`,o:`Ritorno alle attività e al lavoro`,k:`Esercizio progressivo, cammino strutturato`,c:`ADL e lavoro senza evitamento`,e:[1,2,3]},{n:`Cronico`,w:`>3 mesi`,o:`Gestione multidimensionale`,k:`Esposizione graduale, esercizio, sonno, stress, stile di vita; approcci tipo Cognitive Functional Therapy`,c:`Autoefficacia e funzione`,e:[1,2,3]}],
ev:[[`Educazione, rassicurazione e attività/esercizio`,`Centrale`,`Raccomandati da quasi tutte le linee guida (Lin 2019, Corp 2021)`],[`Terapia manuale, massaggio, agopuntura`,`Supporto`,`Se il primo livello non basta`],[`Imaging di routine, riposo a letto, enfasi sulla "postura corretta"`,`Evitare`,`Patologizzano e aumentano la disabilità`]],
f:[[`Lin et al. 2019 – cosa raccomandano le linee guida di alta qualità sul LBP (BJSM)`,`Lin 2019 what does best practice care for musculoskeletal pain look like guidelines`,`PMID 30826805`],[`O'Sullivan et al. 2014 – LBP: dal modello patoanatomico al biopsicosociale`,`O'Sullivan 2014 low back pain beliefs clinical practice`],[`Pocovi et al. 2024 – WalkBack trial (Lancet)`,`Pocovi 2024 walking program low back pain recurrence WalkBack`,`PMID 38908392`],[`Brinjikji et al. 2015 – degenerazione spinale in asintomatici, revisione (AJNR)`,`Brinjikji 2015 imaging features spinal degeneration asymptomatic`,`PMID 25430861`],[`Maher et al. 2017 – Non-specific low back pain (Lancet)`,`Maher 2017 non-specific low back pain Lancet`,`PMID 27745712`]]});

S.push({id:`lbp-radicolare`,d:`Colonna`,t:`Dolore alla gamba: somatico riferito, radicolare e radicolopatia`,nw:1,
sub:`Come distinguere e gestire`,
mat:[MLB],
key:[`Dolore alla gamba ≠ sciatica: distinguere dolore somatico riferito, dolore radicolare e radicolopatia`,`Radicolopatia = conduzione rallentata o bloccata lungo il nervo o la radice: si riconosce con l'esame neurologico, può esistere senza dolore`,`Storia naturale ottima: oltre l'80% recupera e l'ernia si riduce in 12-24 mesi; 87% migliora già a 3 mesi`,`Wait and see con monitoraggio; consulto chirurgico immediato se neurologia progressiva o cauda equina`],
tab:[{t:`Tipi di dolore all'arto inferiore (lezione)`,h:[`Tipo`,`Meccanismo`,`Caratteristiche`],r:[[`Somatico`,`Stimolazione dei nocicettori di strutture lombari`,`Dolore lombare locale`],[`Somatico riferito`,`Convergenza di afferenze nocicettive sui neuroni di secondo ordine`,`Dolore sordo, mal localizzato, alla coscia; nessun deficit neurologico`],[`Radicolare`,`Scariche ectopiche da radice dorsale o ganglio (infiammazione, ischemia, deformazione meccanica)`,`Dolore lancinante, a banda, sotto il ginocchio, test neurodinamici spesso positivi`],[`Radicolopatia`,`Blocco o rallentamento della conduzione`,`Deficit sensitivo, motorio o dei riflessi; spesso stabile, può fluttuare con la posizione (ischemico)`]]}],
inq:[`Il 5-10% dei LBP ha una componente radicolare`,`Gestione: controllo del dolore se il distress è alto; rassicurare sulla storia naturale; programma graduale per normalizzare movimento e ADL`],
red:[`Deficit motorio progressivo, sintomi di cauda equina: consulto chirurgico immediato.`],
yel:[`Paura del movimento e della flessione, catastrofizzazione per la diagnosi di "ernia".`],
tst:[[`Esame neurologico`,`Dermatomi, miotomi, riflessi (vedi scheda Triage).`,`Distingue radicolopatia da dolore radicolare puro.`],[`SLR (Lasègue) e slump`,`Elevazione dell'arto esteso; seduto in flessione progressiva con estensione del ginocchio e dorsiflessione.`,`Meccanosensibilità del nervo sciatico (L4-S1).`],[`PKB (prone knee bend)`,`Flessione del ginocchio da prono.`,`Nervo femorale (L2-L4).`]],
ex:[[`Mobilità neurale (sliders)`,`m`,`2-3×10 · 2-3 volte/die`,`Movimenti alternati che mettono in tensione da un lato e rilasciano dall'altro, senza evocare dolore forte.`,`Tensionare con dolore che persiste.`,`Tensioners leggeri quando tollerati.`],[`Posizioni antalgiche e movimento ripetuto`,`m`,`3×10`,`Cercare le posizioni e direzioni che centralizzano o riducono il dolore.`,`Insistere su direzioni che peggiorano la gamba.`,`Ritorno ai movimenti normali.`],[`Cammino e attività graduata`,`c`,`Durata crescente`,`Contingente al tempo.`,`Riposo prolungato.`,`Esercizio generale.`]],
fasi:[{n:`Acuto`,w:``,o:`Controllo del dolore e rassicurazione`,k:`Monitorare la neurologia`,c:`Dolore gestibile, neurologia stabile`,e:[1,2]},{n:`Recupero`,w:`settimane-mesi`,o:`Normalizzare movimento e ADL`,k:`Mobilità neurale, esercizio graduale`,c:`Riduzione della componente alla gamba`,e:[0,1,2]}],
ev:[[`Rassicurazione, gestione del dolore, riabilitazione graduale`,`Centrale`,`Storia naturale favorevole`],[`Mobilità neurale`,`Supporto`,`Evidenza moderata-limitata`],[`Imaging o chirurgia precoce senza red flags`,`Evitare`,`—`]],
f:[[`Bogduk 2009 – On the definitions and physiology of back pain, referred pain and radicular pain (Pain)`,`Bogduk 2009 definitions physiology back pain referred pain radicular pain`,`PMID 19762151`],[`Schmid et al. 2023 – dolore radicolare e radicolopatia`,`Schmid 2023 radicular pain radiculopathy`,`PMID 37235637`],[`Fourré et al. 2023 – dolore lombare con irradiazione alla gamba (J Man Manip Ther)`,`Fourre 2023 low back related leg pain`,`PMID 35735104`]]});

S.push({id:`lbp-stenosi`,d:`Colonna`,t:`Stenosi lombare`,nw:1,
sub:`Claudicatio neurogena`,
mat:[MLB],
key:[`Condizione anatomica progressiva legata alla degenerazione: non tutti hanno sintomi`,`Claudicatio neurogena: fastidio alle gambe camminando o stando in piedi, migliora a riposo o in flessione lombare`,`Differenziare dalla claudicatio vascolare (piedi freddi, polsi ridotti, indice caviglia-braccio basso)`,`Prima linea riabilitativa; chirurgia di decompressione se il conservativo fallisce e il dolore è disabilitante`],
tab:[{t:`Definizioni (lezione)`,h:[`Tipo`,`Criterio`],r:[[`Centrale assoluta`,`Diametro AP del canale <10 mm`],[`Centrale relativa`,`10-12 mm`],[`Foraminale`,`Diametro <3 mm`]],n:`Più comune a L4-L5; cause: ipertrofia delle faccette e del legamento giallo, peduncoli corti congeniti, spondilolistesi.`},{t:`Claudicatio neurogena vs vascolare`,h:[`Aspetto`,`Neurogena`,`Vascolare`],r:[[`Sollievo`,`Sedersi, flessione lombare`,`Fermarsi in piedi`],[`Salita / bici`,`Spesso meglio (flessione)`,`Peggio`],[`Polsi e temperatura`,`Normali`,`Ridotti, piede freddo`],[`ABI`,`Normale`,`Ridotto`]]}],
red:[`Sintomi di cauda equina a lenta insorgenza (congestione venosa o ischemia delle radici).`,`Deficit neurologico progressivo.`],
yel:[`Paura di camminare, isolamento, decondizionamento.`],
tst:[[`Test del cammino in piano vs in salita o cyclette`,`Tolleranza e sintomi.`,`Neurogena migliora in flessione.`],[`Esame neurologico e polsi periferici`,`Riflessi, forza, polsi pedidii.`,`Differenziale neurogeno/vascolare.`]],
ex:[[`Mobilità in flessione lombare e d'anca`,`m`,`3×10 · quotidiano`,`Ginocchia al petto, flessione da seduto, stretching dei flessori d'anca.`,`Estensioni prolungate.`,`Mobilità globale.`],[`Condizionamento aerobico`,`c`,`20-30 min · 3-5/sett`,`Cyclette o cammino con appoggio (carrello) per la flessione.`,`Interrompere l'attività.`,`Cammino libero più lungo.`],[`Rinforzo di anca e tronco`,`f`,`2-3×10-12`,`Bridge, sit-to-stand, abduttori.`,`Iperlordosi.`,`Carico progressivo.`]],
fasi:[{n:`Educazione`,w:``,o:`Capire i sintomi e le posizioni di sollievo`,k:`Modifica delle attività provocative e dello stile di vita`,c:`Gestione autonoma dei sintomi`,e:[0]},{n:`Condizionamento`,w:``,o:`Flessibilità di anca e colonna, condizionamento`,k:``,c:`Distanza di cammino in aumento`,e:[0,1,2]}],
ev:[[`Riabilitazione: flessibilità, condizionamento, modifica delle attività`,`Centrale`,`Lezione e linee guida`],[`Decompressione chirurgica`,`Supporto`,`Se fallisce il conservativo e il dolore è disabilitante`]],
f:[[`Revisione sulla gestione della stenosi lombare (autore da identificare)`,`lumbar spinal stenosis conservative management physical therapy review`]]});

S.push({id:`scoliosi-ais`,d:`Colonna`,t:`Scoliosi idiopatica (approccio SEAS)`,nw:1,
sub:`Età evolutiva e adulto: autocorrezione, corsetto, chirurgia`,
mat:[MSC],
key:[`Deformità strutturale tridimensionale: flessione laterale sul piano frontale, alterazione (spesso inversione) delle curve sul sagittale, rotazione sull'assiale`,`Obiettivi in crescita: frenare l'evoluzione (fine crescita <30° Cobb), prevenire dolore e disabilità adulti, rachide funzionale, estetica`,`SEAS: l'autocorrezione attiva è la ricerca del miglior allineamento sui 3 piani; poi gli esercizi la "sfidano" per stabilizzarla`,`Consulenza chirurgica: Cobb >45° + disabilità o dolore persistente ingravescente`],
inq:[`Patogenesi (principio di Hueter-Volkmann): la compressione su un'epifisi fertile ne riduce la crescita, la distrazione la accelera → crescita ridotta sul lato concavo, aumentata sul convesso`,`Il peggioramento dipende da eziologia, cambiamenti strutturali rapidi in crescita, degenerazione molto lenta nell'adulto`,`Screening: asimmetrie di fianchi, spalle, scapole, torace; test di Adams con scoliometro (gradi del gibbo, ATR); se positivo → RX e visita specialistica`],
tab:[{t:`Autocorrezione SEAS: i 3 piani`,h:[`Piano`,`Movimento`,`Regole`],r:[[`Frontale – traslazione`,`Dal lato convesso verso il concavo, in obliquo dal basso verso l'alto`,`Lombare: il triangolo della taglia recupera simmetria, bacino fermo, torace stabile, spalle simmetriche. Dorsale: bacino fermo, recuperare la simmetria delle spalle`],[`Orizzontale – derotazione`,`Avanzare con il lato convesso, arretrare con il concavo`,`Es. lombare sx: senso orario con mani sulle SIAS; dorsale dx: antiorario con mani sulle coste; le spinose vanno verso la concavità`],[`Sagittale`,`Recupero della lordosi lombare (sostegno lombare) e mantenimento della cifosi dorsale`,`La cifotizzazione precede, accompagna e segue la correzione dorsale: difficile, almeno non peggiorare`]],n:`Principi: partire dal bacino in direzione craniale; ogni movimento non deve annullare il precedente; iniziare dalle alterazioni maggiori e dai movimenti più semplici; collegare asimmetrie e immagini RX; aggiornare a ogni rivalutazione.`},
{t:`Corsetto (lezione)`,h:[`Aspetto`,`Dettagli`],r:[[`Ruolo`,`Correzione passiva; frenare l'evoluzione vicino al picco di crescita; migliorare l'estetica`],[`Scelta`,`Gradi Cobb, Risser, età ed evolutività`],[`Tipi`,`Elastico (SpineCor), rigidi (Sibilla, Sforzesco)`],[`Durata`,`Fino a fine crescita (dopo Risser 3)`],[`Percorso`,`Fase preparatoria (informazioni, video) → arrivo → full time → riduzione graduale delle ore → abbandono`],[`Fisioterapia`,`Sostegno psicologico, monitoraggio dell'uso (sensore), esercizi di adattamento, stabilizzazione e rinforzo, mobilizzazione su tutti i piani, educazione della famiglia`]]},
{t:`Equilibrio sagittale con filo a piombo (Negrini)`,h:[`Parametro`,`Valore normale`,`Nota`],r:[[`Indice sagittale C7 + L3`,`80 ± 25 mm`,`Correla con la cifosi toracica; cut-off 90 mm per una cifosi di 60° ad alta specificità`],[`C7 – S2`,`20 ± 15 mm`,`Valori alterati indicano perdita di equilibrio sagittale`]]}],
sez:[{h:`Dosaggio SEAS (lezione)`,b:[`Programma domiciliare di circa 20 minuti (slide: "20 MIN 6W", da verificare se 6 volte a settimana), 4-5 esercizi da 4-5 minuti ciascuno`,`Sedute in studio mensili, poi bimestrali verso la fine: valutazione, revisione dell'autocorrezione e degli esercizi, controllo del corsetto`,`Supporti: video esercizi, sedute online, blog`,`Fine terapia: Risser >4/5 o età adulta; attività fisica regolare; monitoraggio annuale se curve >30° Cobb; controllo se compare dolore in carico, sensazione di "schiacciamento" o di essere "piegati in avanti"; attenzione in gravidanza`]},
{h:`Chirurgia e adulto (lezione)`,b:[`Chirurgia: barre e viti garantiscono correzione e stabilità, ma riducono o bloccano la mobilità della zona; esercizi fuori corsetto fino all'intervento`,`Post-operatorio: indicazioni del chirurgo vertebrale; sport di contatto dopo circa 6 mesi (più a lungo con osteotomia e fusione); fisioterapia respiratoria precoce (capacità ridotta nel primo anno); fisioterapia neurologica se complicanze`,`Adulto: dolore che peggiora in carico e con pressione sul gibbo, non sempre legato a un movimento, sollievo in scarico o con autocorrezione sagittale; la perdita di equilibrio sagittale porta dolore e disabilità → autocorrezione sagittale ("sostegno") antalgica, monitoraggio annuale`]},
{h:`Caso clinico della lezione`,b:[`8 anni, Risser 0: curva dorsale dx 38°, lombare sx 19°, gibbo dorsale 8° → quale autocorrezione e quale terapia (esercizi SEAS + corsetto)?`,`Greta: toracica dx 42°, toraco-lombare sx 41°, ATR toracico 7° e toraco-lombare 9°`]}],
red:[`Curva dolorosa nel bambino, curva atipica (toracica sinistra), deficit neurologico, progressione rapida: escludere forme secondarie.`],
yel:[`Impatto psicologico del corsetto, scarsa compliance, immagine corporea.`],
tst:[[`Test di Adams con scoliometro`,`Flessione anteriore del tronco; misurare l'ATR del gibbo.`,`Screening: se positivo RX e visita.`],[`Filo a piombo`,`Distanze da C7, L3, S2.`,`Equilibrio sagittale e cifosi.`],[`Valutazione radiografica`,`Cobb, Risser, rotazione.`,`Entità, maturità scheletrica, evolutività.`]],
ex:[[`Traslazione laterale (lombare o dorsale)`,`c`,`4-5 min · nel programma da 20 min`,`Dal convesso verso il concavo in obliquo dal basso in alto, bacino fermo.`,`Muovere il bacino o le spalle.`,`Mantenerla durante compiti e respirazione.`],[`Derotazione`,`c`,`4-5 min`,`Avanzare con il lato convesso e arretrare con il concavo, mani su SIAS o coste.`,`Perdere la traslazione impostata prima.`,`Combinata con gli altri piani.`],[`Sostegno lombare e mantenimento della cifosi`,`c`,`4-5 min`,`Recupero attivo della lordosi lombare evitando l'estensione dorso-lombare.`,`Iperestendere il tratto dorso-lombare.`,`Cifotizzazione del tratto dorsale.`],[`Stabilizzazione in autocorrezione`,`f`,`4-5 min · 3-5 serie`,`Mantenere la correzione e aggiungere sfide: equilibrio, carichi, coordinazione occhio-mano, gesti di vita e sport.`,`Perdere la correzione sotto sforzo.`,`Esercizi più difficili e quotidianità.`]],
fasi:[{n:`Apprendimento`,w:`prime sedute`,o:`Autocorrezione sui piani più importanti`,k:`Movimenti semplici, collegati alle immagini RX`,c:`Autocorrezione eseguita autonomamente`,e:[0,1,2]},{n:`Stabilizzazione`,w:`mesi`,o:`Sfidare la correzione`,k:`Esercizi di stabilità, deficit specifici (equilibrio, retrazioni, piccoli deficit neurologici)`,c:`Correzione mantenuta sotto sfida`,e:[0,1,2,3]},{n:`Quotidianità e sport`,w:`fino a fine crescita`,o:`Autocorrezione nella vita e nello sport`,k:`Integrazione con il corsetto se prescritto; esercizi nello svezzamento (Zaina 2009)`,c:`Risser >4/5, curva stabile`,e:[3]}],
ev:[[`Esercizi specifici per la scoliosi (SEAS) e corsetto secondo indicazione`,`Centrale`,`Linee guida SOSORT 2016 e nazionali (Negrini)`],[`Esercizi nello svezzamento dal corsetto`,`Supporto`,`Evitano la perdita di correzione (Zaina 2009)`],[`Attività fisica generica come unico trattamento in curve evolutive`,`Evitare`,`Non sostituisce esercizi specifici e corsetto`]],
f:[[`Negrini et al. 2018 – linee guida SOSORT 2016 sul trattamento della scoliosi idiopatica in crescita`,`Negrini 2016 SOSORT guidelines orthopaedic rehabilitation idiopathic scoliosis`,`PMID 29435499`],[`Romano et al. 2015 – SEAS: approccio evidence-based agli esercizi specifici`,`Romano 2015 SEAS scientific exercises approach scoliosis`,`PMID 25729406`],[`Zaina et al. 2009 – esercizi nello svezzamento dal corsetto`,`Zaina 2009 specific exercises brace weaning adolescent idiopathic scoliosis`,`PMID 19351395`],[`Negrini et al. 2012 – validazione delle distanze dal filo a piombo`,`Negrini 2012 plumbline distances screening sagittal plane deformities`]]});

S.push({id:`cervicobrachialgia`,d:`Colonna`,t:`Cervicobrachialgia e sindrome dello stretto toracico`,nw:1,
sub:`Diagnosi differenziale del dolore di spalla`,
mat:[MSP],
key:[`Dolore progressivo di collo, spalla e braccio fino alle dita, irradiato dal plesso brachiale`,`Può essere confuso con un problema di spalla: la differenza la fanno anamnesi, sintomi associati e test`,`Spurling positivo e distrazione che allevia: cluster per radicolopatia cervicale`],
inq:[`Sintomi: rigidità nucale, dolore diffuso, torcicollo, parestesie e intorpidimento`,`Valutare sempre il rachide cervicale nei dolori di spalla atipici`],
tst:[[`ULTT A (mediano)`,`ABD di spalla + supinazione ed estensione del polso → ER di spalla → estensione del gomito → inclinazione controlaterale del collo.`,`Riproduzione dei sintomi neurali.`],[`Spurling`,`Compressione + inclinazione omolaterale al sintomo.`,`Dolore radicolare.`],[`Neck distraction`,`Trazione (pompage) del capo.`,`Positivo se i sintomi diminuiscono.`],[`Rotazione cervicale`,`Rotazione omolaterale al sintomo.`,`Positivo se <60°.`],[`Ross (EAST)`,`ABD 90° + ER + gomito a 90°, aprire e chiudere le mani per 3 minuti.`,`Stretto toracico.`],[`Adson`,`Lieve ABD ed estensione dell'omero + estensione e rotazione omolaterale del collo; polso radiale.`,`Compressione negli scaleni.`],[`Eden`,`Come sopra + compressione della clavicola.`,`Spazio costo-claveare (I costa).`],[`Wright`,`ABD 90° + ER + gomito 90°, poi iperabduzione.`,`Piccolo pettorale.`]],
red:[`Deficit motorio progressivo, segni di mielopatia (goffaggine delle mani, disturbi del cammino, Hoffmann), segni vascolari (pallore, edema, freddo).`],
yel:[`Paura del movimento del collo, stress, postura lavorativa prolungata.`],
ex:[[`Mobilità neurale del mediano (slider)`,`m`,`2×10 · 2/die`,`Movimenti alternati di polso e collo senza tensione elevata.`,`Evocare parestesie persistenti.`,`Tensioners.`],[`Retrazione cervicale e mobilità`,`m`,`3×10`,`Movimenti indolori nelle direzioni che riducono i sintomi.`,`Insistere su direzioni che periferizzano.`,`Rinforzo dei flessori profondi.`],[`Rinforzo scapolare`,`f`,`3×12`,`Trapezio inferiore, gran dentato, row.`,`Shrug.`,`Carico progressivo.`]],
fasi:[{n:`Acuto`,w:``,o:`Ridurre i sintomi irradiati`,k:`Educazione, posizioni di sollievo, mobilità`,c:`Centralizzazione o riduzione dei sintomi`,e:[0,1]},{n:`Recupero`,w:``,o:`Mobilità e forza`,k:``,c:`Funzione e test neurodinamici migliorati`,e:[0,1,2]}],
ev:[[`Esercizio, mobilità ed educazione`,`Centrale`,`Linee guida sul neck pain`],[`Mobilità neurale e trazione`,`Supporto`,`Selettivo`]],
f:[[`Wainner et al. 2003 – cluster clinico per la radicolopatia cervicale (Spine)`,`Wainner 2003 clinical prediction rule cervical radiculopathy`,`PMID 12544957`],[`Revisione sulla sindrome dello stretto toracico (autore da identificare)`,`thoracic outlet syndrome diagnosis provocative tests review`]]});

S.push({id:`colonna-spondilolisi`,d:`Colonna`,t:`Spondilolisi nell'atleta giovane`,nw:1,
sub:`Frattura da stress della pars interarticularis, gestione conservativa e rientro`,
key:[`Sospettarla nell'adolescente sportivo con dolore lombare in estensione, soprattutto se unilaterale e da sport con estensione e rotazione ripetute`,`Sede tipica: L5, più raramente L4`,`Lesioni precoci (con edema osseo alla RM) hanno maggiore probabilità di guarigione ossea: diagnosi tempestiva`,`Il trattamento è quasi sempre conservativo: stop dalle attività provocative, poi riabilitazione progressiva`],
inq:[`Difetto o frattura da stress della pars interarticularis, la porzione di arco vertebrale tra faccetta articolare superiore e inferiore`,`Meccanismo: carichi ripetuti in estensione e rotazione lombare (nel rugby: mischia, sollevamento in touche, placcaggio; anche ginnastica, lanci, cricket)`,`Più frequente durante la crescita, quando l'osso della pars è più vulnerabile`,`Bilaterale può evolvere in spondilolistesi: scivolamento anteriore della vertebra, graduato con Meyerding (I-IV)`,`Molti difetti vecchi sono asintomatici: l'imaging va interpretato con la clinica`],
tab:[{t:`Stadi alla RM/TC (classificazione di Sairyo, sintesi)`,h:[`Stadio`,`Imaging`,`Implicazione`],r:[[`Precoce`,`Edema della pars alla RM, linea di frattura sottile o assente`,`Buona probabilità di guarigione ossea con stop dallo sport`],[`Progressivo`,`Linea di frattura evidente, edema presente`,`Guarigione possibile ma meno probabile, tempi più lunghi`],[`Terminale`,`Pseudoartrosi (gap sclerotico), edema assente`,`Guarigione ossea improbabile: obiettivo è l'assenza di sintomi e la funzione`]],n:`Classificazione da verificare sulla fonte originale prima dell'uso clinico.`},
{t:`Gradi di Meyerding (spondilolistesi)`,h:[`Grado`,`Scivolamento`],r:[[`I`,`0-25%`],[`II`,`25-50%`],[`III`,`50-75%`],[`IV`,`75-100%`]],n:`Oltre il 100% si parla di spondiloptosi.`}],
red:[`Deficit neurologico (radicolopatia L5, debolezza, alterazioni sfinteriche): invio urgente.`,`Dolore notturno costante, febbre, calo ponderale: escludere tumore o infezione.`,`Spondilolistesi di grado elevato o in progressione nel giovane in crescita: valutazione ortopedica.`],
yel:[`Paura di perdere la stagione o il posto in squadra, pressione di allenatori e famiglia a rientrare presto.`,`Catastrofizzazione del termine "frattura vertebrale".`],
tst:[[`Estensione lombare in stazione eretta`,`Estensione attiva, anche combinata con rotazione (quadrante).`,`Dolore lombare localizzato: compatibile con lesione della pars, ma non specifico.`],[`One-leg hyperextension (stork test)`,`In appoggio su una gamba, estensione lombare; si confrontano i due lati.`,`Accuratezza diagnostica bassa: non basta per confermare né per escludere.`],[`Palpazione e percussione`,`Pressione sui processi spinosi L4-L5-S1.`,`Dolorabilità focale; uno "scalino" palpabile fa sospettare spondilolistesi.`],[`Esame neurologico`,`Riflessi, forza per miotomi, sensibilità, SLR.`,`Escludere compromissione radicolare.`],[`Lunghezza degli hamstring`,`Angolo popliteo o SLR passivo.`,`La rigidità degli ischiocrurali è frequente (risposta protettiva).`],[`Imaging (medico)`,`RM come primo esame (nessuna radiazione, vede l'edema); TC per definire la frattura.`,`Stadio della lesione e prognosi di guarigione.`]],
ex:[[`Isometrici del tronco in posizione neutra (dead bug, side plank sulle ginocchia)`,`c`,`3×20-30 s · RPE 3-5 · quotidiano`,`Bacino e lombare in posizione neutra, respirazione libera, movimenti degli arti lenti.`,`Inarcare la schiena o trattenere il respiro.`,`Arti più distesi, side plank completo, poi carichi esterni.`],[`Mobilità di anca e torace (flessori d'anca, rotazioni toraciche)`,`m`,`2×8-10 · RPE 2-3 · quotidiano`,`Allungare i flessori d'anca con bacino in retroversione; ruotare il torace mantenendo ferma la lombare.`,`Compensare con estensione lombare.`,`Più ampiezza, poi integrazione in movimenti funzionali.`],[`Hip hinge e rinforzo dei glutei (bridge, stacco rumeno leggero)`,`f`,`3×10-12 → 4×6-8 · RPE 5-8 · 2-3/sett`,`Movimento dalle anche con colonna neutra.`,`Iperestendere la lombare a fine movimento.`,`Bridge su una gamba, stacco con carico, trap bar.`],[`Anti-rotazione ed anti-estensione (Pallof press, rollout)`,`c`,`3×8-10 · RPE 5-7 · 2-3/sett`,`Resistere alla rotazione o all'estensione mantenendo il tronco fermo.`,`Perdita della posizione neutra a fine serie.`,`Elastico più duro, rollout più lungo, posizioni in ginocchio o in piedi.`],[`Reintroduzione graduale dell'estensione`,`c`,`2-3×6-8 · RPE 3-5 · 2-3/sett`,`Estensione lombare attiva in scarico, poi in carico, solo se asintomatica.`,`Forzare l'ampiezza con dolore.`,`Carico e velocità crescenti, poi gesti sport-specifici.`],[`Lavoro specifico rugby (spinta in mischia, placcaggio, sollevamento in touche)`,`p`,`volumi bassi → pieni · RPE 6-9 · 2-3/sett`,`Dal macchinario da mischia e dai colpitori alla situazione con avversario, con progressione di carico e intensità.`,`Passare al contatto pieno senza tappe intermedie.`,`Più intensità, durata e imprevedibilità.`]],
fasi:[{n:`Protezione`,w:`circa 0-6 sett (orientativo)`,o:`Ridurre il dolore e il carico sulla pars`,k:`Stop da sport e attività provocative (estensione e rotazione), educazione, attività aerobica non provocativa, mobilità e controllo in posizione neutra; eventuale corsetto su indicazione medica`,c:`Assenza di dolore nelle attività quotidiane`,e:[0,1]},
{n:`Ricondizionamento`,w:`circa 6-12 sett (orientativo)`,o:`Forza e controllo del tronco e degli arti inferiori`,k:`Rinforzo progressivo in neutro, anti-rotazione e anti-estensione, carico progressivo`,c:`Estensione lombare asintomatica, forza e resistenza del tronco adeguate`,e:[0,1,2,3]},
{n:`Ritorno allo sport`,w:`dopo circa 3 mesi (orientativo)`,o:`Tollerare estensione, rotazione e contatto`,k:`Reintroduzione dell'estensione, corsa e cambi di direzione, gesti specifici di ruolo, contatto progressivo`,c:`Criteri di rientro soddisfatti`,e:[2,3,4,5]}],
ev:[[`Gestione conservativa (stop dalle attività provocative + esercizio)`,`Centrale`,`Buoni esiti clinici nella maggior parte dei casi; evidenza da studi osservazionali e revisioni, non da trial randomizzati`],[`Esercizi di stabilizzazione del tronco`,`Supporto`,`Razionale plausibile, evidenza di qualità limitata`],[`Corsetto`,`Supporto`,`Uso variabile tra i centri; non dimostrato superiore al solo stop dalle attività`],[`Chirurgia (riparazione della pars o artrodesi)`,`Supporto`,`Riservata a dolore persistente dopo almeno 6 mesi di conservativo, deficit neurologici o listesi di grado elevato`],[`Ritorno precoce allo sport con dolore in estensione`,`Evitare`,`Rischio di progressione della lesione e di mancata guarigione`]],
rts:{intro:`Non esistono criteri validati specifici per il rugby: quelli che seguono sono una proposta operativa che combina le indicazioni della letteratura (sintomi e funzione) con le richieste del ruolo. Il via libera finale spetta al medico.`,c:[[`Sintomi`,`Dolore in attività quotidiane, corsa ed estensione lombare`,`Assenti`,`Il dolore in estensione indica che la pars non tollera ancora il carico.`],[`Imaging (se richiesto dal medico)`,`Controllo RM o TC`,`Guarigione o lesione stabile e asintomatica`,`La guarigione ossea non è obbligatoria: conta che la lesione sia stabile e non dia sintomi.`],[`Forza e resistenza del tronco`,`Side plank e test di resistenza degli estensori; forza degli arti inferiori`,`Simmetria e valori pari a prima dell'infortunio (proposta)`,`Il tronco deve trasmettere la forza in mischia e nel placcaggio.`],[`Gesti di estensione e rotazione`,`Sollevamento in touche, passaggio, calcio`,`Senza dolore, a piena intensità`,`Sono il meccanismo di lesione.`],[`Contatto progressivo`,`Colpitori → contatto controllato → situazione di gioco`,`Tollerato senza sintomi nelle 24 ore successive`,`Il contatto pieno è il carico più alto per la colonna.`]],pre:[`Allenamenti completi con la squadra senza sintomi`,`Fiducia dell'atleta nel gesto di contatto`],nota:`Tempi indicativi in letteratura: rientro spesso intorno ai 3-6 mesi, variabile con stadio, sport e ruolo.`},
f:[[`Alqarni et al. 2015 – test clinici per la diagnosi di spondilolisi e spondilolistesi, revisione sistematica (da verificare)`,`Alqarni clinical tests diagnose lumbar spondylolysis spondylolisthesis systematic review`,`PMID 25797410`],[`Klein et al. 2009 – efficacia del trattamento conservativo della spondilolisi, meta-analisi (da verificare)`,`Klein 2009 efficacy conservative treatment spondylolysis meta-analysis`,`PMID 19352240`],[`Sairyo et al. – stadiazione della spondilolisi con RM e TC (articolo da identificare)`,`Sairyo spondylolysis stage MRI CT bone healing`],[`Panteliadis et al. 2016 – esiti nell'atleta con spondilolisi, chirurgico vs conservativo (da verificare)`,`Panteliadis athletic population spondylolysis outcomes surgical repair conservative`,`PMID 27556003`]]});

S.push({id:`fratture-costali-contatto`,d:`Colonna`,t:`Fratture costali e dolore toracico da contatto`,nw:1,
sub:`Urto nel placcaggio e nel ruck: escludere le complicanze, respirare bene, tornare al contatto per gradi`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Meccanismo tipico nel rugby: urto diretto sul torace (spalla o ginocchio dell'avversario, caduta sul pallone) o compressione sotto più giocatori nel ruck e nel maul`,`Prima di tutto escludere le complicanze: pneumotorace, volet costale, lesioni di milza o fegato nelle fratture delle ultime coste (pratica clinica)`,`La radiografia vede male le fratture costali; l'ecografia ha sensibilità 89% e specificità 98% rispetto alla TC (Gilbertson 2022, studi ad alto rischio di bias)`,`La priorità riabilitativa è respirare a fondo e tossire bene: nei pazienti ospedalizzati l'allenamento respiratorio riduce atelettasie e infezioni polmonari (Zhang 2025, 9 RCT)`,`Tempi di rientro: nel baseball professionistico circa 7 settimane per le fratture traumatiche e 14 per quelle da stress (Gopalkrishnan 2026); nel rugby non ci sono studi`],
inq:[`Spettro clinico: contusione della parete toracica, lesione della cartilagine costale o della giunzione costo-condrale, frattura costale composta o scomposta. La gestione dell'atleta è simile, cambiano i tempi; le lesioni cartilaginee non si vedono alla radiografia (pratica clinica)`,`Le coste medie sono le più colpite dai traumi diretti; una frattura delle prime coste indica un trauma ad alta energia, una frattura delle ultime coste può associarsi a lesioni di milza, fegato o rene (pratica clinica e testi)`,`Nella popolazione ospedaliera generale (Battle 2011, 29 studi) il rischio di morte dopo trauma toracico chiuso cresce con 3 o più fratture costali (OR 2,02), età di almeno 65 anni (OR 1,98), malattie preesistenti (OR 2,43) e polmonite (OR 5,24). Nell'atleta giovane il messaggio utile è che più coste rotte e complicanze respiratorie indicano un trauma serio`,`Il dolore limita il respiro: respiro superficiale e tosse inefficace favoriscono atelettasia e polmonite. Per questo controllo del dolore e respiro sono la base del trattamento (linea guida EAST, Galvagno 2016: raccomandazione condizionale per analgesia multimodale o epidurale, prove molto deboli, pazienti ospedalizzati)`,`Le fratture da stress sono un'altra entità, da sovraccarico ripetuto (lanciatori, canottieri): nel baseball hanno richiesto circa il doppio del tempo delle traumatiche (Gopalkrishnan 2026)`,`Stop al contatto, non all'attività: la condizione fisica e la forza degli arti inferiori si possono mantenere fin dai primi giorni (proposta operativa)`,`Lacuna: non sono stati trovati studi su fratture costali o contusioni toraciche nel rugby, né criteri validati per tornare al contatto; le linee guida riguardano pazienti ospedalizzati e politraumatizzati, non l'atleta con frattura isolata`],
tab:[{t:`Imaging delle fratture costali: cosa dicono le fonti`,z:`V`,h:[`Esame`,`Dato (fonte)`],r:[[`Radiografia del torace`,`Poco affidabile per le fratture costali; l'ecografia sembra superiore, ma 13 studi piccoli e a rischio di bias non permettono conclusioni definitive (Battle 2018)`],[`Ecografia rispetto alla TC`,`Sensibilità 89,3%, specificità 98,4% (Gilbertson 2022, 6 studi, 663 pazienti)`],[`Ecografia positiva`,`LR+ 55,7: una irregolarità della corticale conferma quasi sempre la frattura`],[`Ecografia negativa`,`LR- 0,11: rende la frattura molto meno probabile, ma non la esclude del tutto`],[`TC`,`Standard di riferimento negli studi; nei traumi importanti cerca anche le complicanze`],[`Limite`,`Rischio di bias alto, soprattutto nella selezione dei pazienti; nessuno studio sugli atleti`]]},{t:`Rientro dopo frattura costale nel baseball professionistico (Gopalkrishnan 2026)`,z:`R`,h:[`Dato`,`Valore`],r:[[`Fratture analizzate`,`121: 57 traumatiche, 54 da stress, 10 non specificate`],[`Assenza media, fratture traumatiche`,`47,4 giorni (circa 7 settimane)`],[`Assenza media, fratture da stress`,`98,1 giorni (circa 14 settimane)`],[`Lanciatori con frattura da stress`,`17,6 settimane, il tempo più lungo`],[`Prestazione al rientro`,`Calo in 1 indicatore su 15 nei giocatori di movimento: impatto minimo`],[`Limite`,`Sport senza placcaggio: i tempi non si trasferiscono direttamente al rugby`]]}],
red:[`Fiato corto, respiro rapido, saturazione bassa, dolore che peggiora o crepitio sotto la pelle (enfisema sottocutaneo): sospetto pneumotorace, invio urgente.`,`Un tratto della parete che rientra in inspirazione invece di espandersi (movimento paradosso): volet costale, urgenza.`,`Frattura delle ultime coste con dolore addominale, dolore alla spalla sinistra, pallore o malessere: sospetta lesione di milza, fegato o rene, invio urgente.`,`Sangue nell'espettorato o nelle urine.`,`Fratture delle prime coste o dello sterno: trauma ad alta energia, rischio di lesioni vascolari o cardiache.`,`Febbre e tosse produttiva nei giorni successivi: sospetta polmonite.`,`Dolore toracico senza un trauma chiaro o con sintomi cardiaci: non è un problema muscoloscheletrico fino a prova contraria.`,`Queste red flag vengono dalla pratica clinica: le fonti della scheda studiano solo i fattori di rischio di mortalità nella popolazione ospedaliera (Battle 2011).`],
yel:[`Paura di prendere un colpo sul lato colpito: tecnica di placcaggio modificata, ci si gira per proteggerlo.`,`Respiro volutamente superficiale per non sentire dolore.`,`Pressione per rientrare a stagione in corso, magari con un'infiltrazione o un'imbottitura.`],
tst:[[`Palpazione e compressione del torace`,`Pressione diretta sulla costa; poi compressione antero-posteriore e laterale del torace lontano dal punto doloroso.`,`Dolore localizzato sul punto suggerisce frattura o lesione costo-condrale. Orienta, non conferma: le fonti non riportano dati di accuratezza (pratica clinica).`],[`Respiro profondo, tosse e rotazione del tronco`,`Dolore da 0 a 10 durante inspirazione massima, colpo di tosse e rotazione da seduto.`,`Misura principale di monitoraggio, da ripetere a ogni seduta.`],[`Segni di allarme respiratori`,`Frequenza respiratoria, saturimetro, osservazione della parete durante il respiro, palpazione per crepitio sottocutaneo.`,`Qualsiasi alterazione richiede invio medico urgente (vedi red flag).`],[`Imaging`,`Su indicazione medica: RX, ecografia o TC.`,`RX poco sensibile (Battle 2018). Ecografia: sensibilità 89,3%, specificità 98,4% rispetto alla TC (Gilbertson 2022).`],[`Mobilità del tronco`,`Rotazione da seduto con un bastone sulle spalle e flessione laterale in piedi, confronto tra i due lati.`,`Monitoraggio e criterio di rientro.`]],
ex:[[`Respiro profondo e tosse assistita`,`c`,`10 respiri lenti con pausa di 2-3 s a fine inspirazione, ogni 1-2 ore da sveglio; 2-3 colpi di tosse assistita alla fine (proposta operativa)`,`Seduto o in piedi, un cuscino o la mano premuti sul lato doloroso; inspirazione lenta dal naso allargando la parte bassa e laterale del torace. Spirometro incentivante se disponibile.`,`Respirare in modo superficiale per evitare il dolore; trattenere la tosse.`,`Respiro con le braccia in elevazione, poi respiro profondo durante camminata e cyclette.`],[`Mobilità toracica`,`m`,`2×8-10 per lato · quotidiano (proposta operativa)`,`Rotazioni da seduto con le braccia incrociate, open book sul fianco sano, gatto-cammello, flessione laterale in piedi.`,`Forzare nel dolore acuto o aggiungere carichi in rotazione nelle prime settimane.`,`Rotazioni in piedi con bastone, poi con elastico.`],[`Condizione aerobica`,`f`,`3-5 sedute/sett. di 20-40 min, intensità guidata da respiro e dolore (proposta operativa)`,`Camminata veloce e cyclette dai primi giorni se tollerate; poi corsa continua, intervalli e sprint.`,`Correre con il respiro bloccato o con dolore che sale durante la seduta.`,`Intervalli ad alta intensità e sprint ripetuti.`],[`Isometrici del tronco`,`i`,`3-4×20-30 s · RPE 4-6 (proposta operativa)`,`Pallof press con elastico, plank sulle ginocchia, side plank prima sul lato sano e poi sul lato colpito. Respirare durante tutta la tenuta.`,`Apnea e spinta a glottide chiusa durante la tenuta.`,`Plank completo, side plank sul lato colpito, carico aggiunto.`],[`Forza globale`,`f`,`3-4×6-10 · RPE 6-8 · 2-3/sett. (proposta operativa)`,`Arti inferiori da subito senza carico sul torace (leg press, split squat con manubri, trap bar leggera); arti superiori in progressione: rematore, distensioni con manubri, poi panca e trazioni.`,`Carichi massimali a glottide chiusa o bilanciere appoggiato sul torace prima che respiro e tosse siano liberi.`,`Carichi massimali, panca con bilanciere, trazioni zavorrate.`],[`Potenza e lanci`,`p`,`3-4×5-8 (proposta operativa)`,`Lanci di palla medica in rotazione e al petto, salti, accelerazioni, passaggi lunghi.`,`Introdurli quando la tosse fa ancora male.`,`Palle mediche più pesanti, ricezione della palla medica sul petto.`],[`Progressione al contatto`,`p`,`2-3 sedute/sett. guidate dai sintomi (proposta operativa)`,`Cadute a terra e rotolamenti; impatto su scudo e sacco prima con il lato sano, poi con quello colpito; placcaggio controllato, ruck, contatto pieno.`,`Saltare tappe; girarsi nel placcaggio per proteggere il lato colpito.`,`Contatto in situazioni di gioco.`]],
fasi:[{n:`Protezione e respiro`,w:`circa 0-2 sett. (indicativo)`,o:`Controllo del dolore, respiro profondo e tosse efficace, esclusione delle complicanze`,k:`Analgesia decisa dal medico; niente contatto né carichi sul torace; camminata e cyclette se tollerate`,c:`Respiro profondo e tosse possibili con dolore lieve; nessun segno di complicanze`,e:[0,1,2]},{n:`Mobilità e carico senza impatto`,w:`circa 2-4 sett. (indicativo)`,o:`Mobilità del tronco, condizione aerobica, forza degli arti inferiori`,k:`Corsa continua quando il respiro profondo non fa più male`,c:`Rotazioni del tronco quasi senza dolore; corsa continua tollerata`,e:[0,1,2,3,4]},{n:`Forza e potenza`,w:`circa 4-6 sett. (indicativo)`,o:`Forza completa di tronco e arti superiori, sprint, lanci`,k:`Introdurre panca, trazioni e lanci in rotazione`,c:`Nessun dolore alla palpazione e alla compressione del torace (proposta operativa)`,e:[2,3,4,5]},{n:`Contatto`,w:`in media circa 7 sett. per le fratture traumatiche nel baseball (Gopalkrishnan 2026); per il rugby nessun dato`,o:`Progressione al placcaggio e al ruck`,k:`Prima impatti con il lato sano, poi con quello colpito`,c:`Criteri del capitolo del rientro`,e:[4,5,6]}],
ev:[[`Allenamento respiratorio e mobilizzazione precoce`,`Centrale`,`Metanalisi di 9 RCT, 811 pazienti (Zhang 2025): meno atelettasie (RR 0,23) e infezioni polmonari (RR 0,24), degenza più breve, ossigenazione e funzione polmonare migliori, nessun effetto sui versamenti pleurici. Pazienti ospedalizzati, non atleti con frattura isolata`],[`Controllo del dolore sufficiente a respirare e tossire`,`Supporto`,`Linea guida EAST (Galvagno 2016): raccomandazione condizionale per analgesia multimodale o epidurale, prove di qualità molto bassa in pazienti ospedalizzati. La scelta dei farmaci è medica`],[`Ecografia per confermare la frattura`,`Supporto`,`Sensibilità 89% e specificità 98% rispetto alla TC (Gilbertson 2022, rischio di bias alto); probabilmente migliore della RX (Battle 2018, nessuna conclusione definitiva)`],[`Mantenere condizione fisica e forza degli arti inferiori dai primi giorni`,`Supporto`,`Pratica clinica e proposta operativa: nessuno studio nelle fonti della scheda`],[`Fasciature toraciche strette e riposo a letto`,`Evitare`,`Pratica clinica: limitano l'espansione del torace e favoriscono il respiro superficiale; nessuno studio nelle fonti della scheda`],[`Contatto prima che respiro, tosse e compressione del torace siano senza dolore`,`Evitare`,`Proposta operativa: nuovo trauma su un osso non ancora consolidato`]],
rts:{intro:`Non esistono criteri validati per tornare al contatto dopo una frattura costale, né studi sul rugby. L'unico dato sui tempi viene dal baseball professionistico: circa 7 settimane per le fratture traumatiche e 14 per quelle da stress (Gopalkrishnan 2026), in uno sport senza placcaggio. Le soglie qui sotto sono proposte operative.`,c:[[`Via libera medica`,`Visita ed eventuale imaging`,`Complicanze escluse o risolte: nessun pneumotorace, versamento o lesione addominale in corso`,`Prendere colpi con una complicanza non risolta è pericoloso.`],[`Respiro e tosse`,`Dolore da 0 a 10 durante inspirazione massima, tosse e starnuto`,`0/10 (proposta operativa)`,`Nel rugby si respira a fondo e in fretta sotto sforzo massimale: il respiro libero dice che la parete regge il carico interno.`],[`Palpazione e compressione`,`Pressione sul focolaio e compressione antero-posteriore e laterale del torace`,`Nessun dolore (proposta operativa)`,`Segno clinico di consolidazione; un placcaggio comprime il torace molto più della mano.`],[`Mobilità del tronco`,`Rotazione da seduto e flessione laterale, confronto tra i lati`,`Simmetrica e senza dolore (proposta operativa)`,`Passare, placcare e rialzarsi da terra richiedono una rotazione piena.`],[`Capacità di corsa`,`Sessione completa di corsa con sprint ripetuti e accelerazioni`,`Completata senza dolore e senza respiro limitato (proposta operativa)`,`Sotto fatica il respiro è più profondo e frequente: è lì che una parete non guarita fa male.`],[`Contatto progressivo`,`Cadute a terra, scudo, sacco, placcaggio controllato, ruck, contatto pieno`,`Tutta la progressione senza dolore (proposta operativa)`,`Nel rugby il contatto è il test finale.`],[`Fiducia`,`Domanda diretta: ti senti pronto a placcare e a finire sotto un ruck?`,`Risposta sicura, senza girarsi per proteggere il lato (proposta operativa)`,`La paura cambia la tecnica di placcaggio ed espone ad altri traumi.`]],pre:[`Primo contatto pieno in allenamento, non in partita (proposta operativa)`,`Protezioni imbottite per il torace: nessuno studio nelle fonti della scheda; possono aiutare la fiducia ma non sono una garanzia di sicurezza (lacuna)`,`Se dopo un colpo ricompaiono dolore al respiro o fiato corto: stop e visita medica`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`I tempi del baseball (Gopalkrishnan 2026, 121 fratture) non si trasferiscono direttamente al rugby, dove il torace viene colpito a ogni placcaggio. Le linee guida su dolore e respiro riguardano pazienti ospedalizzati e politraumatizzati.`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione delle fratture costali nel rugby (lacuna)`,`Programmi di riscaldamento come Activate riducono gli infortuni nel rugby giovanile (Hislop 2017), senza dati specifici sul torace`,`Allenare la tecnica di placcaggio e di caduta a terra (proposta operativa, senza studi specifici)`,`Nessuna prova sull'efficacia delle protezioni imbottite del torace (lacuna)`]}],
f:[[`Gopalkrishnan et al. 2026 – fratture costali nel baseball professionistico: epidemiologia, prestazione e ritorno allo sport (Orthop J Sports Med)`,`Gopalkrishnan 2026 rib fracture professional baseball players return to sport`,`PMID 41625508`],[`Battle et al. 2011 – fattori di rischio di mortalità nel trauma toracico chiuso, revisione sistematica e metanalisi (Injury)`,`Battle 2011 risk factors mortality blunt chest wall trauma systematic review meta-analysis`,`PMID 21256488`],[`Gilbertson et al. 2022 – accuratezza dell'ecografia toracica per le fratture costali, revisione sistematica e metanalisi (Ann Emerg Med)`,`Gilbertson 2022 chest ultrasonography rib fractures blunt chest trauma meta-analysis`,`PMID 35461720`],[`Battle et al. 2018 – ecografia polmonare e radiografia del torace nella diagnosi delle fratture costali, revisione sistematica (Emerg Med J)`,`Battle 2018 lung ultrasound chest radiography diagnosis rib fractures systematic review`,`PMID 30470688`],[`Galvagno et al. 2016 – gestione del dolore nel trauma toracico chiuso, linea guida EAST (J Trauma Acute Care Surg)`,`Galvagno 2016 pain management blunt thoracic trauma EAST practice management guideline`,`PMID 27533913`],[`Zhang et al. 2025 – allenamento respiratorio nella riabilitazione delle fratture costali, metanalisi di RCT (BMC Sports Sci Med Rehabil)`,`Zhang 2025 respiratory training rehabilitation rib fracture meta-analysis`,`PMID 40128895`],[`Hislop et al. 2017 – programma di controllo del movimento nel rugby scolastico, RCT a cluster (BJSM)`,`Hislop 2017 movement control exercise programme schoolboy rugby`,`PMID 28515056`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});
